style.css:
@-moz-document domain("roblox.com") {
/* Hintergrundbild für die gesamte Seite */
  html, body {
    background: url("https://images.steamusercontent.com/ugc/33314777909570923/F2FAA1C213B36EB95CCF40691744896EDD8CD294/?imw=5000&imh=5000&ima=fit&impolicy=Letterbox&imcolor=%23000000&letterbox=false")
                no-repeat center center fixed !important;
    background-size: cover !important;
    background-attachment: fixed !important;
  }

  /* Optional: Overlay, um Texte und Buttons besser lesbar zu machen */
  body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.3); /* Transparenz anpassen nach Bedarf */
    pointer-events: none;
    z-index: 0;
  }

  /* Alle Roblox Inhalte über dem Overlay */
  body > * {
    position: relative;
    z-index: 1;
  }

  /* Optional: Cards und Panels leicht transparent, damit Hintergrund durchscheint */
  .card, .panel, .scroller, .game-card-container {
    background: rgba(20, 20, 20, 0.85) !important; 
    border-radius: 8px !important;
  }

  /* Texte auf Roblox besser lesbar machen */
  .text, .text-label, h1, h2, h3, p, span {
    color: #ffffff !important;
  }

  /* Buttons optisch hervorheben */
  .btn, .rbx-btn, button {
    background: rgba(255,255,255,0.1) !important;
    color: #ffffff !important;
    border-radius: 6px !important;
    border: 1px solid rgba(255,255,255,0.2) !important;
    transition: all 0.2s ease;
  }
  .btn:hover, .rbx-btn:hover, button:hover {
    background: rgba(106,176,255,0.3) !important;
    color: #ffffff !important;
  }
}
